import json, os, subprocess, sys
from pathlib import Path
root = Path('/kaggle/working/source'); root.mkdir(exist_ok=True)
files = json.loads('{"model.py": "\\"\\"\\"Decoder language model initialized from scratch; no downloaded model weights.\\"\\"\\"\\nfrom dataclasses import dataclass, asdict\\nimport math\\nimport torch\\nfrom torch import nn\\nfrom torch.nn import functional as F\\n\\n\\n@dataclass\\nclass Config:\\n    vocab_size: int = 32768\\n    dim: int = 640\\n    layers: int = 16\\n    heads: int = 10\\n    hidden_dim: int = 1792\\n    context: int = 1024\\n    rope_base: float = 10000.0\\n\\n\\nclass RMSNorm(nn.Module):\\n    def __init__(self, dim):\\n        super().__init__()\\n        self.weight = nn.Parameter(torch.ones(dim))\\n\\n    def forward(self, x):\\n        z = x.float()\\n        return (z * torch.rsqrt(z.square().mean(-1, keepdim=True) + 1e-6)).to(x.dtype) * self.weight\\n\\n\\nclass Attention(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.heads = cfg.heads\\n        self.head_dim = cfg.dim // cfg.heads\\n        assert cfg.dim % cfg.heads == 0 and self.head_dim % 2 == 0\\n        self.qkv = nn.Linear(cfg.dim, 3 * cfg.dim, bias=False)\\n        self.out = nn.Linear(cfg.dim, cfg.dim, bias=False)\\n        inv = cfg.rope_base ** (-torch.arange(0, self.head_dim, 2).float() / self.head_dim)\\n        angles = torch.outer(torch.arange(cfg.context).float(), inv)\\n        self.register_buffer(\'cos\', angles.cos(), persistent=False)\\n        self.register_buffer(\'sin\', angles.sin(), persistent=False)\\n\\n    def rotate(self, x):\\n        length = x.size(-2)\\n        cos = self.cos[:length].to(x.dtype)[None, None]\\n        sin = self.sin[:length].to(x.dtype)[None, None]\\n        even, odd = x[..., 0::2], x[..., 1::2]\\n        return torch.stack((even * cos - odd * sin, even * sin + odd * cos), dim=-1).flatten(-2)\\n\\n    def forward(self, x):\\n        b, t, d = x.shape\\n        q, k, v = self.qkv(x).reshape(b, t, 3, self.heads, self.head_dim).permute(2, 0, 3, 1, 4).unbind(0)\\n        z = F.scaled_dot_product_attention(self.rotate(q), self.rotate(k), v, is_causal=True)\\n        return self.out(z.transpose(1, 2).contiguous().view(b, t, d))\\n\\n\\nclass Block(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.norm1, self.norm2 = RMSNorm(cfg.dim), RMSNorm(cfg.dim)\\n        self.attn = Attention(cfg)\\n        self.gate = nn.Linear(cfg.dim, cfg.hidden_dim, bias=False)\\n        self.up = nn.Linear(cfg.dim, cfg.hidden_dim, bias=False)\\n        self.down = nn.Linear(cfg.hidden_dim, cfg.dim, bias=False)\\n\\n    def forward(self, x):\\n        x = x + self.attn(self.norm1(x))\\n        z = self.norm2(x)\\n        return x + self.down(F.silu(self.gate(z)) * self.up(z))\\n\\n\\nclass Brain(nn.Module):\\n    def __init__(self, cfg=None):\\n        super().__init__()\\n        self.cfg = cfg or Config()\\n        self.embedding = nn.Embedding(self.cfg.vocab_size, self.cfg.dim)\\n        self.blocks = nn.ModuleList([Block(self.cfg) for _ in range(self.cfg.layers)])\\n        self.norm = RMSNorm(self.cfg.dim)\\n        self.head = nn.Linear(self.cfg.dim, self.cfg.vocab_size, bias=False)\\n        self.head.weight = self.embedding.weight\\n        self.apply(self._init)\\n        for block in self.blocks:\\n            nn.init.normal_(block.attn.out.weight, std=0.02 / math.sqrt(2 * self.cfg.layers))\\n            nn.init.normal_(block.down.weight, std=0.02 / math.sqrt(2 * self.cfg.layers))\\n\\n    @staticmethod\\n    def _init(module):\\n        if isinstance(module, (nn.Linear, nn.Embedding)):\\n            nn.init.normal_(module.weight, std=0.02)\\n\\n    def forward(self, tokens, targets=None):\\n        if tokens.shape[1] > self.cfg.context:\\n            raise ValueError(\'Sequence exceeds configured context\')\\n        x = self.embedding(tokens)\\n        for block in self.blocks:\\n            x = block(x)\\n        logits = self.head(self.norm(x))\\n        if targets is None:\\n            return logits\\n        return F.cross_entropy(logits.reshape(-1, self.cfg.vocab_size).float(), targets.reshape(-1))\\n\\n    def parameter_count(self):\\n        return sum(p.numel() for p in self.parameters())\\n\\n    @torch.no_grad()\\n    def generate(self, tokens, new_tokens=100, temperature=0.8, top_k=40):\\n        self.eval()\\n        for _ in range(new_tokens):\\n            logits = self(tokens[:, -self.cfg.context:])[:, -1].float() / max(temperature, 1e-5)\\n            cutoff = torch.topk(logits, min(top_k, logits.shape[-1]))[0][:, -1:]\\n            logits = logits.masked_fill(logits < cutoff, float(\'-inf\'))\\n            token = torch.multinomial(logits.softmax(-1), 1)\\n            tokens = torch.cat((tokens, token), dim=1)\\n        return tokens\\n", "probe.py": "import json, os, time\\nfrom pathlib import Path\\nimport torch\\nimport torch.distributed as dist\\nfrom torch.nn.parallel import DistributedDataParallel as DDP\\nfrom model import Brain, Config\\n\\ndef main():\\n    dist.init_process_group(\'nccl\')\\n    rank = int(os.environ[\'LOCAL_RANK\'])\\n    torch.cuda.set_device(rank)\\n    torch.manual_seed(20261003)\\n    torch.set_num_threads(2)\\n    net = Brain().cuda(rank)\\n    params = net.parameter_count()\\n    ddp = DDP(net, device_ids=[rank])\\n    opt = torch.optim.AdamW(net.parameters(), lr=3e-4, fused=True)\\n    scaler = torch.amp.GradScaler(\'cuda\', init_scale=4096)\\n    batch, length = 8, net.cfg.context\\n    x = torch.randint(0, net.cfg.vocab_size, (batch, length + 1), device=rank)\\n    losses = []\\n    steps, warmup = 16, 4\\n    dist.barrier()\\n    begin = time.monotonic()\\n    for i in range(steps):\\n        opt.zero_grad(set_to_none=True)\\n        with torch.autocast(\'cuda\', dtype=torch.float16):\\n            loss = ddp(x[:, :-1], x[:, 1:])\\n        scaler.scale(loss).backward()\\n        scaler.unscale_(opt)\\n        torch.nn.utils.clip_grad_norm_(net.parameters(), 1.0)\\n        scaler.step(opt)\\n        scaler.update()\\n        torch.cuda.synchronize()\\n        losses.append(loss.item())\\n        if i == warmup - 1:\\n            dist.barrier()\\n            begin = time.monotonic()\\n    duration = torch.tensor(time.monotonic() - begin, device=rank)\\n    dist.all_reduce(duration, op=dist.ReduceOp.MAX)\\n    if rank == 0:\\n        rate = (steps - warmup) * batch * length * dist.get_world_size() / duration.item()\\n        report = {\'parameters\': params, \'gpus\': [torch.cuda.get_device_name(i) for i in range(torch.cuda.device_count())],\\n                  \'tokens_per_second\': rate, \'micro_batch_per_gpu\': batch, \'context\': length,\\n                  \'peak_memory_gb_per_gpu\': torch.cuda.max_memory_allocated() / 1e9,\\n                  \'initial_loss\': losses[0], \'last_loss\': losses[-1],\\n                  \'estimated_hours_2b_compute_only\': 2e9 / rate / 3600,\\n                  \'torch\': torch.__version__, \'status\': \'PASS\'}\\n        Path(\'/kaggle/working/probe.json\').write_text(json.dumps(report, indent=2))\\n        print(json.dumps(report), flush=True)\\n    dist.destroy_process_group()\\n\\nif __name__ == \'__main__\':\\n    main()\\n"}')
for name, content in files.items(): (root/name).write_text(content)
os.environ['NCCL_P2P_DISABLE'] = '1'
os.environ['NCCL_IB_DISABLE'] = '1'
subprocess.run([sys.executable, '-m', 'torch.distributed.run', '--standalone', '--nproc_per_node=2', str(root/'probe.py')], check=True, cwd=root)
